var DESC={"cancerI":"암이 생긴 <b>부위마다</b> 따로 진단비가 나오는 담보입니다(원발 · 전이 기준은 상품마다 다름). 한 번 받고 끝나는 일반암과 다릅니다.","canLiv":"암 진단 뒤 <b>매달</b> 정해진 기간 생활비가 나옵니다. 치료로 일을 못 하는 동안의 월급 자리입니다.","radIM":"종양 모양에 맞춰 세기를 조절해 쏘는 방사선 치료(IMRT · 토모테라피 등)를 받을 때 나옵니다.","robotS":"다빈치 같은 로봇으로 암 수술을 받을 때 나옵니다. 로봇수술은 대부분 <b>비급여</b>라 본인 부담이 큽니다.","bhLiv":"뇌혈관 · 심장 질환 진단 뒤 <b>매달</b> 생활비가 나옵니다. 재활로 일을 쉬는 동안을 받칩니다.","disLiv":"큰 후유장해(기준 %는 상품마다 다름)가 남으면 <b>매달</b> 생활자금이 나옵니다.","silD":"입원해서 실제로 쓴 병원비를 <b>쓴 만큼</b> 돌려줍니다. 자기부담금은 뺍니다.","silDO":"통원 진료비를 <b>1회당 한도</b> 안에서 돌려줍니다.","silDP":"약국에서 산 처방약값을 <b>1회당 한도</b> 안에서 돌려줍니다.","silA":"다쳐서 입원했을 때의 병원비를 <b>쓴 만큼</b> 돌려줍니다.","silAO":"다쳐서 통원했을 때의 진료비를 돌려줍니다.","silAP":"다쳐서 받은 처방약값을 돌려줍니다.","silNB":"도수치료·주사·MRI 같은 <b>비급여</b>를 따로 정한 한도로 돌려줍니다.","cancer":"암으로 <b>확진되면 영수증 없이</b> 목돈이 한 번에 나옵니다. 치료 방법을 돈 때문에 못 고르는 일을 막는 <b>첫 번째 방어선</b>입니다.","cancer2":"갑상선·제자리암 같은 <b>유사암</b>은 일반암보다 훨씬 적게 나옵니다. 「암 걸리면 나온다」가 아니라 <b>어떤 암이냐</b>가 금액을 가릅니다.","cantx":"수술·항암약물·방사선 중 <b>급여로 받은 치료</b>에 따라 나옵니다. <b>비급여 주요치료비는 따로</b> 적습니다.","target":"표적·면역 항암제는 <b>회당 수백만원</b>이고 실손으로 다 안 됩니다. 이 특약이 그 자리를 메웁니다.","antican":"항암 방사선·약물치료를 <b>받을 때마다</b> 나옵니다.","outC":"암 치료로 <b>통원한 날마다</b> 나옵니다. 치료는 5년을 갑니다.","brain":"뇌에 생기는 병 <b>전부</b>(I60~I69)를 봅니다. <b>가장 넓은 범위</b>라 어떤 뇌질환이 와도 열립니다.","stroke":"뇌출혈·뇌경색만 봅니다. 뇌질환의 <b>약 3분의 2</b>에서 열립니다.","brainh":"터진 것만 봅니다. 뇌질환의 <b>10분의 1</b>도 안 되는 경우에만 열립니다 — 이것만 있으면 <b>거의 안 나옵니다.</b>","braini":"막힌 것만 봅니다. 뇌졸중의 대부분은 뇌경색입니다.","brainS":"뇌혈관을 <b>수술</b>했을 때 나옵니다. 진단비와 <b>따로</b> 나옵니다.","brainT":"막힌 혈관을 녹이는 치료를 받으면 나옵니다.","heartA":"심장에 생기는 병 <b>전부</b>를 봅니다. 가장 넓은 범위입니다.","heart":"혈관이 좁아져 생기는 병(협심증·심근경색)을 봅니다. 심장병의 <b>약 60%</b>입니다.","mi":"혈관이 <b>완전히 막힌</b> 경우만 봅니다. 심장병의 <b>10분의 1</b> 정도입니다.","heartOp":"스텐트·우회로 같은 <b>시술·수술</b>을 받으면 나옵니다.","arrhy":"부정맥 진단에 나옵니다.","surg":"병으로 <b>수술을 받으면</b> 종류를 가리지 않고 나옵니다.","surgA":"다쳐서 <b>수술을 받으면</b> 나옵니다.","surg5D":"수술을 1~5종으로 나눠 <b>무거울수록 크게</b> 줍니다.","surg5A":"상해 수술을 1~5종으로 나눠 줍니다.","surgN":"뇌·심혈관·신부전·폐렴 같은 <b>큰 병 수술</b>에 목돈이 나옵니다.","surgL":"편도·디스크·치핵처럼 <b>흔한 수술</b>에 나옵니다. 실제로 가장 자주 쓰는 담보입니다.","inpD":"병으로 입원한 <b>날마다</b> 나옵니다. 병원비가 아니라 <b>그날의 생활비</b>입니다.","inpA":"다쳐서 입원한 날마다 나옵니다.","icu":"중환자실에 있는 날마다 <b>더 크게</b> 나옵니다.","nurUD":"간병인을 <b>실제로 쓴 날</b> 나옵니다. 하루 12~15만원이 드는 자리입니다.","ltcF":"장기요양 등급을 받으면 <b>매달</b> 나옵니다. 끝나는 날이 정해져 있지 않은 유일한 보장입니다.","dem2":"중증치매로 진단되면 목돈이 나옵니다.","deathD":"병으로 세상을 떠났을 때 <b>남은 가족</b>에게 갑니다.","deathA":"사고로 세상을 떠났을 때 갑니다. 보통 질병사망보다 크게 잡습니다.","disabD":"병으로 몸에 <b>장해가 남으면</b> 정도에 따라 나옵니다.","disabA":"사고로 장해가 남으면 나옵니다. <b>3%부터</b> 나오는지가 핵심입니다.","liab":"가족이 남에게 <b>피해를 입혔을 때</b> 물어 줍니다. 보험료가 아주 싼데 쓸 일이 잦습니다.","carAcc":"교통사고로 <b>형사합의</b>가 필요할 때 나옵니다.","lawyer":"변호사를 선임해야 할 때 나옵니다. <b>경찰조사 단계부터</b> 되는지가 다릅니다.","fine":"교통사고 벌금을 대신 내줍니다.","carHurt":"자동차 사고로 다치면 <b>급수에 따라</b> 나옵니다.","cancerH":"위·폐·간·췌장·뇌·혈액암처럼 <b>치료비가 크고 생존율이 낮은</b> 암에 일반암과 <b>겹쳐서</b> 더 나옵니다.","cancerR":"완치 뒤 <b>다시 진단</b>되면 나옵니다. 암은 5년을 지켜보는 병이라 이 자리가 비면 두 번째가 무섭습니다.","cancerM":"다른 장기로 <b>퍼졌을 때</b> 나옵니다. 치료비가 가장 크게 드는 국면입니다.","immuno":"키트루다·옵디보 같은 <b>면역항암제</b>입니다. 급여가 안 되면 <b>연 수천만원</b>입니다.","anticanD":"세포독성 항암제(화학요법)를 맞을 때 나옵니다. <b>표적·면역과 별개</b>로 열립니다.","proton":"양성자·중입자 치료입니다. <b>회당 수백만원</b>이고 대부분 비급여입니다.","canSurg":"암으로 <b>수술받으면</b> 나옵니다. 일반 수술비와 <b>따로</b> 열립니다.","canNur":"암 치료 중 <b>간병인을 쓴 날</b> 나옵니다. 항암 중에는 혼자 못 지냅니다.","circD":"뇌와 심장을 <b>한 줄기</b>로 봅니다 — 어느 쪽이 와도 열리는 <b>가장 넓은 그물</b>입니다.","circS":"뇌·심혈관을 <b>수술</b>했을 때 나옵니다. 진단비와 따로입니다.","circT":"막힌 혈관을 <b>녹이거나 뽑는</b> 치료를 받으면 나옵니다. 골든타임에 하는 그 시술입니다.","stent":"스텐트·개두술처럼 <b>몸을 여는</b> 시술입니다. 「관혈」인지 「비관혈」인지가 지급을 가릅니다.","icuC":"중환자실에 있는 날마다 나옵니다. 순환계 사건은 <b>중환자실부터</b> 시작합니다.","inpC":"암으로 입원한 <b>날마다</b> 나옵니다. 항암은 며칠씩 여러 번이라 <b>횟수가 쌓입니다.</b>","cantxN":"수술·항암약물·방사선 치료 중 <b>비급여</b>로 쓴 치료를 따로 봅니다. 급여 주요치료비와 <b>별개로</b> 나옵니다 — 신약·로봇수술처럼 건강보험이 안 되는 자리입니다.","fracS":"뼈가 부러져 <b>수술</b>을 받으면 나옵니다. 골절 진단비와 <b>따로</b> 나옵니다.","cast":"깁스(석고·반깁스)를 하면 나옵니다. 골절이 아니어도 되는지는 <b>약관마다 다릅니다.</b>","frac":"뼈가 부러졌다고 <b>진단</b>되면 나옵니다. 치아 파절은 빠지는 것이 보통입니다. 넘어짐 하나로 가장 자주 쓰는 상해 담보입니다.","burnS":"화상으로 <b>수술</b>(피부이식 등)을 받으면 나옵니다.","burn":"화상으로 진단되면 나옵니다. <b>심재성 2도 이상</b>부터인지, 중증화상만인지가 지급을 가릅니다.","brainTx":"뇌혈관 질환으로 <b>혈전용해 · 혈관중재술 · 수술</b> 같은 주요 치료를 받은 <b>해마다</b> 나오는 치료비입니다(연 1회 등 · 상품마다 다름). 진단비와 따로 나옵니다.","heartW":"<b>특정 심장질환</b>(상품이 정한 심부전 · 판막 · 부정맥 등)으로 진단되면 나옵니다. 심혈관질환 · 허혈성과 <b>범위가 다르니</b> 약관의 질병 표를 봐야 합니다.","heartTx":"심장 질환으로 <b>혈관중재술(스텐트) · 수술</b> 같은 주요 치료를 받은 <b>해마다</b> 나오는 치료비입니다(상품마다 다름).","cvTx":"뇌 · 심장(순환계) 질환으로 주요 치료를 받은 <b>해마다</b> 나오는 치료비입니다 — 「통합치료비」 라고도 부릅니다. 뇌와 심장 <b>둘 다</b>에 열립니다(범위 · 횟수는 상품마다 다름).","nurNS":"간호사가 간병까지 하는 <b>간호·간병통합서비스 병동</b>에 입원한 날마다 나옵니다. 간병인을 직접 쓰는 「간병인사용일당」 과 다른 담보입니다.","ltcD":"국민건강보험 <b>장기요양 등급</b>(1~2등급 · 1~5등급 등 상품마다)을 받으면 <b>목돈 한 번</b> 나옵니다. 매달 나오는 장기요양 급여와 다릅니다."};
var ROW={},NAME={},SNAME={},UNIT={},SSTD={},COV={},MID={},MIC={};
(function(){var i,j;for(i=0;i<STD.length;i++)for(j=0;j<STD[i].rows.length;j++){
  var r=STD[i].rows[j];
  ROW[r.k]=r;NAME[r.k]=r.n;SNAME[r.k]=r.s||(''+r.n).replace(/\s*\([^)]*\)\s*/g,'').trim()||r.n;UNIT[r.k]=r.u;SSTD[r.k]=r.std;COV[r.k]=r.cov||null;r.d=DESC[r.k]||'';
  MID[r.k]=STD[i].mid;MIC[r.k]=STD[i].ic;
}})();
var UNIT_LB={L:'만원',D:'/일',M:'/월',A:'한도'},UNIT_FULL={L:'목돈',D:'하루',M:'매달',A:'한도'};
/* 이름 맞추기 — KB 표준담보명·원문명 어느 쪽이 와도 */
function mapName(name){
  var T=(''+name).replace(/\s+/g,''),i,j,q;
  for(i=0;i<STD.length;i++)for(j=0;j<STD[i].rows.length;j++){
    var r=STD[i].rows[j];
    for(q=0;q<(r.syn||[]).length;q++){
      var idx=T.indexOf((''+r.syn[q]).replace(/\s+/g,''));
      if(idx<0)continue;
      if(r.not){
        var head=T.slice(Math.max(0,idx-7),idx+8),z,bad=false;
        for(z=0;z<r.not.length;z++)if(head.indexOf(r.not[z])>=0){bad=true;break;}
        if(bad)continue;
      }
      return r.k;
    }
  }
  return null;
}
